"use client";

import { createContext, type ReactNode, use, useCallback, useEffect, useMemo, useRef, useState } from "react";
import { cx } from "../utils/cx";
import type { Tone } from "./badge";
import { CloseIcon } from "../icons/interface";

export type ToastOptions = {
  title: string;
  description?: string;
  tone?: Extract<Tone, "neutral" | "info" | "success" | "warning" | "danger">;
  /** Milliseconds before it leaves. `0` keeps it until dismissed. Default 5000. */
  duration?: number;
  /** One quiet action, such as "Undo". The toast is dismissed after it runs. */
  action?: { label: string; onClick: () => void };
};

type ToastEntry = Required<Pick<ToastOptions, "title" | "tone" | "duration">> &
  Omit<ToastOptions, "tone" | "duration"> & { id: string; leaving?: boolean };

type ToastApi = { toast: (options: ToastOptions) => string; dismiss: (id?: string) => void };
const ToastContext = createContext<ToastApi | null>(null);

/** Raises toasts from any client component under `ToastProvider`. */
export function useToast(): ToastApi {
  const ctx = use(ToastContext);
  if (!ctx) throw new Error("useToast must be used inside <ToastProvider>");
  return ctx;
}

export type ToastProviderProps = {
  children: ReactNode;
  /** Most toasts shown at once; the oldest leaves first. Default 4. */
  limit?: number;
  /** Where the stack sits. Default `bottom-right`. */
  position?: "bottom-right" | "bottom-center" | "top-right";
  /** Accessible name of the notifications region. */
  label?: string;
};

/**
 * A queue of transient messages in a polite live region. The stack lives in the top layer, so it stays above open
 * dialogs. Timers pause while the pointer or keyboard focus is inside the stack, and Escape clears it.
 */
export function ToastProvider({
  children,
  limit = 4,
  position = "bottom-right",
  label = "Notifications",
}: ToastProviderProps) {
  const [toasts, setToasts] = useState<ToastEntry[]>([]);
  const [paused, setPaused] = useState(false);
  const counter = useRef(0);
  const region = useRef<HTMLDivElement>(null);

  // dismissing marks a toast as leaving so it can play its exit; it is removed once that has finished
  const dismiss = useCallback(
    (id?: string) => setToasts((all) => all.map((t) => (!id || t.id === id ? { ...t, leaving: true } : t))),
    [],
  );
  const remove = useCallback((id: string) => setToasts((all) => all.filter((t) => t.id !== id)), []);
  const toast = useCallback(
    (o: ToastOptions) => {
      const id = `hm-toast-${++counter.current}`;
      const entry: ToastEntry = { ...o, id, tone: o.tone ?? "neutral", duration: o.duration ?? 5000 };
      setToasts((all) => [...all, entry].slice(-limit));
      return id;
    },
    [limit],
  );
  const api = useMemo(() => ({ toast, dismiss }), [toast, dismiss]);

  const has = toasts.length > 0;
  useEffect(() => {
    const el = region.current;
    if (!el || typeof el.showPopover !== "function") return;
    if (has && !el.matches(":popover-open")) el.showPopover();
    else if (!has && el.matches(":popover-open")) el.hidePopover();
  }, [has]);

  return (
    <ToastContext value={api}>
      {children}
      <div
        ref={region}
        popover="manual"
        role="region"
        aria-label={label}
        aria-live="polite"
        className="hm-toast-region"
        data-position={position}
        onPointerEnter={() => setPaused(true)}
        onPointerLeave={() => setPaused(false)}
        onFocus={() => setPaused(true)}
        onBlur={(e) => {
          if (!e.currentTarget.contains(e.relatedTarget)) setPaused(false);
        }}
        onKeyDown={(e) => {
          if (e.key === "Escape") dismiss();
        }}
      >
        <ol className="hm-toast-list">
          {toasts.map((t) => (
            <ToastItem key={t.id} entry={t} paused={paused} dismiss={dismiss} remove={remove} />
          ))}
        </ol>
      </div>
    </ToastContext>
  );
}

function ToastItem({
  entry,
  paused,
  dismiss,
  remove,
}: { entry: ToastEntry; paused: boolean; dismiss: (id: string) => void; remove: (id: string) => void }) {
  const remaining = useRef(entry.duration);
  useEffect(() => {
    if (!entry.leaving) return;
    const t = setTimeout(() => remove(entry.id), 360);
    return () => clearTimeout(t);
  }, [entry.leaving, entry.id, remove]);
  useEffect(() => {
    if (!entry.duration || paused || entry.leaving) return;
    const started = Date.now();
    const timer = setTimeout(() => dismiss(entry.id), remaining.current);
    return () => {
      clearTimeout(timer);
      remaining.current = Math.max(0, remaining.current - (Date.now() - started));
    };
  }, [paused, entry.duration, entry.id, entry.leaving, dismiss]);
  return (
    <li className="hm-toast-slot" data-leaving={entry.leaving ? "" : undefined}>
      <div className={cx("hm-toast")} data-tone={entry.tone}>
        <div className="hm-toast-body">
          <p className="hm-toast-title">{entry.title}</p>
          {entry.description ? <p className="hm-toast-description">{entry.description}</p> : null}
        </div>
        {entry.action ? (
          <button
            type="button"
            className="hm-toast-action"
            onClick={() => {
              entry.action?.onClick();
              dismiss(entry.id);
            }}
          >
            {entry.action.label}
          </button>
        ) : null}
        <button
          type="button"
          className="hm-toast-close"
          aria-label={`Dismiss: ${entry.title}`}
          onClick={() => dismiss(entry.id)}
        >
          <CloseIcon size={12} />
        </button>
      </div>
    </li>
  );
}
